_query:
SELECT ?item ?ru ?uk ?coord ?cap ?capRu ?capCoord ?dissolved WHERE {
  ?item p:P131/ps:P131 wd:Q170036 ; rdfs:label ?ru .
  FILTER(lang(?ru)="ru" && (CONTAINS(?ru, "район") || CONTAINS(?ru, "округ")))
  OPTIONAL { ?item rdfs:label ?uk FILTER(lang(?uk)="uk") }
  OPTIONAL { ?item wdt:P625 ?coord }
  OPTIONAL { ?item wdt:P36 ?cap . ?cap wdt:P625 ?capCoord . OPTIONAL { ?cap rdfs:label ?capRu FILTER(lang(?capRu)="ru") } }
  OPTIONAL { ?item wdt:P576 ?dissolved }
}
